css:
/* ═══════════════════════════════════════════════════════════════
   AI & Agentic Collection V2: Premium CSS Animations
   50 animated icons with gradient fills, multi-element stagger,
   draw-in effects, glow pulses, and spectrum cascade
   ═══════════════════════════════════════════════════════════════ */

/* Shared: allow transforms to overflow cell bounds */
.si-anim svg { overflow: visible; }

/* ━━━ V2 HERO ICONS (10) ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━ */

/* ──── 1. SPARKLE ──────────────────────────────────────────────
   Animation story: Main star pops in with elastic bounce,
   then 3 accent dots twinkle in sequence with color cycling.
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .xznek0 .n8l1r5,
.icon-card:hover .xznek0 .n8l1r5 {
  animation: fa08ar 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
  transform-origin: center;
}
.si-icon-cell:hover .xznek0 .ba1np5,
.icon-card:hover .xznek0 .ba1np5 {
  animation: q0e7v2 0.8s ease 0.1s both;
}
.si-icon-cell:hover .xznek0 .dcs6nk,
.icon-card:hover .xznek0 .dcs6nk {
  animation: q0e7v2 0.8s ease 0.25s both;
}
.si-icon-cell:hover .xznek0 .ouvkbd,
.icon-card:hover .xznek0 .ouvkbd {
  animation: q0e7v2 0.8s ease 0.4s both;
}
@keyframes fa08ar {
  0%   { transform: scale(0.5) rotate(-15deg); opacity: 0.3; }
  60%  { transform: scale(1.15) rotate(5deg); opacity: 1; }
  100% { transform: scale(1) rotate(0); opacity: 1; }
}
@keyframes q0e7v2 {
  0%   { transform: scale(0); opacity: 0; }
  50%  { transform: scale(1.5); opacity: 1; }
  100% { transform: scale(1); opacity: 0.8; }
}

/* ──── 2. AGENT-LOOP ──────────────────────────────────────────
   Animation story: Dashed ring spins, orbiting dots chase
   around the center node with different speeds.
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .f91tcy .di0fcm,
.icon-card:hover .f91tcy .di0fcm {
  animation: l0lz4v 2s linear infinite;
  transform-origin: center;
}
.si-icon-cell:hover .f91tcy .b3gncj,
.icon-card:hover .f91tcy .b3gncj {
  animation: kk5i10 1s ease infinite;
  transform-origin: center;
}
.si-icon-cell:hover .f91tcy .lhq3km,
.icon-card:hover .f91tcy .lhq3km {
  animation: acwa41 1.5s linear infinite;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .f91tcy .pll55w,
.icon-card:hover .f91tcy .pll55w {
  animation: acwa41 1.5s linear 0.5s infinite;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .f91tcy .cw35r0,
.icon-card:hover .f91tcy .cw35r0 {
  animation: acwa41 1.5s linear 1s infinite;
  transform-origin: 12px 12px;
}
@keyframes l0lz4v {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}
@keyframes kk5i10 {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.15); }
}
@keyframes acwa41 {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

/* ──── 3. STREAMING ───────────────────────────────────────────
   Animation story: Text lines cascade in top-to-bottom with
   staggered fade-in, cursor blinks at bottom.
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .xxyxwf .t753cg,
.icon-card:hover .xxyxwf .t753cg {
  animation: n7czq9 0.8s ease both;
}
.si-icon-cell:hover .xxyxwf .gloiwq,
.icon-card:hover .xxyxwf .gloiwq {
  animation: n7czq9 0.8s ease 0.12s both;
}
.si-icon-cell:hover .xxyxwf .okp7k2,
.icon-card:hover .xxyxwf .okp7k2 {
  animation: n7czq9 0.8s ease 0.24s both;
}
.si-icon-cell:hover .xxyxwf .s0ntbp,
.icon-card:hover .xxyxwf .s0ntbp {
  animation: n7czq9 0.8s ease 0.36s both;
}
.si-icon-cell:hover .xxyxwf .fgbpcq,
.icon-card:hover .xxyxwf .fgbpcq {
  animation: t19j22 0.6s steps(2) infinite;
}
@keyframes n7czq9 {
  0%   { transform: translateX(-4px); opacity: 0; }
  100% { transform: translateX(0); opacity: 1; }
}
@keyframes t19j22 {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

/* ──── 4. GUARDRAIL ───────────────────────────────────────────
   Animation story: Shield border draws in, then glow pulse.
   Checkmark draws in last as confirmation.
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .tihxmg .oug1rq,
.icon-card:hover .tihxmg .oug1rq {
  stroke-dasharray: 60;
  stroke-dashoffset: 60;
  animation: eqrepj 0.8s ease forwards;
}
.si-icon-cell:hover .tihxmg .rs3fz4,
.icon-card:hover .tihxmg .rs3fz4 {
  animation: a1gbba 1s ease 0.4s both;
}
.si-icon-cell:hover .tihxmg .t0vwg8,
.icon-card:hover .tihxmg .t0vwg8 {
  stroke-dasharray: 15;
  stroke-dashoffset: 15;
  animation: wlihdm 0.4s ease 0.7s forwards;
}
@keyframes eqrepj {
  to { stroke-dashoffset: 0; }
}
@keyframes a1gbba {
  0%   { opacity: 0; }
  50%  { opacity: 0.25; }
  100% { opacity: 0.15; }
}
@keyframes wlihdm {
  to { stroke-dashoffset: 0; }
}

/* ──── 5. RAG-PIPELINE ────────────────────────────────────────
   Animation story: Document fades in, data flows through
   pipe nodes, output document appears at end.
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .kk8xwh .pyoyg9,
.icon-card:hover .kk8xwh .pyoyg9 {
  animation: wny52i 0.6s ease;
}
.si-icon-cell:hover .kk8xwh .ihqbc3,
.icon-card:hover .kk8xwh .ihqbc3 {
  stroke-dasharray: 20;
  stroke-dashoffset: 20;
  animation: eqrepj 0.6s ease 0.2s forwards;
}
.si-icon-cell:hover .kk8xwh .aqdt98,
.icon-card:hover .kk8xwh .aqdt98 {
  animation: pd56ye 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) 0.35s both;
}
.si-icon-cell:hover .kk8xwh .iaqe0y,
.icon-card:hover .kk8xwh .iaqe0y {
  animation: pd56ye 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) 0.5s both;
}
.si-icon-cell:hover .kk8xwh .dszjse,
.icon-card:hover .kk8xwh .dszjse {
  animation: wny52i 0.5s ease 0.65s both;
}
@keyframes wny52i {
  0%   { opacity: 0.05; transform: scale(0.95); }
  50%  { opacity: 0.3; transform: scale(1.02); }
  100% { opacity: 0.2; transform: scale(1); }
}
@keyframes pd56ye {
  0%   { transform: scale(0); }
  100% { transform: scale(1); }
}

/* ──── 6. EMBEDDING ───────────────────────────────────────────
   Animation story: Scattered dots converge toward center
   core, core grows as dots arrive.
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .upo7wq .ikkfnt,
.icon-card:hover .upo7wq .ikkfnt {
  animation: iuxbvs 0.7s ease both;
}
.si-icon-cell:hover .upo7wq .rzlyah,
.icon-card:hover .upo7wq .rzlyah {
  animation: js51je 0.7s ease 0.1s both;
}
.si-icon-cell:hover .upo7wq .mgqkvd,
.icon-card:hover .upo7wq .mgqkvd {
  animation: a7h78f 0.7s ease 0.15s both;
}
.si-icon-cell:hover .upo7wq .k0hxfy,
.icon-card:hover .upo7wq .k0hxfy {
  animation: vihstw 0.7s ease 0.2s both;
}
.si-icon-cell:hover .upo7wq .ug6qmw,
.icon-card:hover .upo7wq .ug6qmw {
  animation: n8zwyw 0.7s ease 0.25s both;
}
.si-icon-cell:hover .upo7wq .pezfii,
.icon-card:hover .upo7wq .pezfii {
  animation: rd3p17 0.7s ease 0.3s both;
}
.si-icon-cell:hover .upo7wq .k6mrgr,
.icon-card:hover .upo7wq .k6mrgr {
  animation: oj6gk2 0.5s ease 0.5s both;
  transform-origin: center;
}
@keyframes iuxbvs { to { transform: translate(4px, 5px); opacity: 0; } }
@keyframes js51je { to { transform: translate(-4px, 5px); opacity: 0; } }
@keyframes a7h78f { to { transform: translate(6px, -1px); opacity: 0; } }
@keyframes vihstw { to { transform: translate(-6px, -1px); opacity: 0; } }
@keyframes n8zwyw { to { transform: translate(2px, -6px); opacity: 0; } }
@keyframes rd3p17 { to { transform: translate(-3px, -5px); opacity: 0; } }
@keyframes oj6gk2 {
  0%   { transform: scale(1); }
  60%  { transform: scale(1.4); }
  100% { transform: scale(1.2); }
}

/* ──── 7. MODEL ───────────────────────────────────────────────
   Animation story: 3D cube rotates, faces shift opacity
   creating depth perception.
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .iemvrk svg,
.icon-card:hover .iemvrk svg {
  animation: rzkyz6 1s ease;
  transform-origin: center;
}
.si-icon-cell:hover .iemvrk .tz2v9i,
.icon-card:hover .iemvrk .tz2v9i {
  animation: zba8hh 1s ease;
}
.si-icon-cell:hover .iemvrk .l1fpl0,
.icon-card:hover .iemvrk .l1fpl0 {
  animation: tk1f3t 1s ease;
}
@keyframes rzkyz6 {
  0%   { transform: rotateY(0deg) scale(1); }
  50%  { transform: rotateY(15deg) scale(1.05); }
  100% { transform: rotateY(0deg) scale(1); }
}
@keyframes zba8hh {
  0%   { opacity: 0.5; }
  50%  { opacity: 0.7; }
  100% { opacity: 0.5; }
}
@keyframes tk1f3t {
  0%   { opacity: 0.3; }
  50%  { opacity: 0.15; }
  100% { opacity: 0.3; }
}

/* ──── 8. PROMPT ──────────────────────────────────────────────
   Animation story: Prompt line draws in from left, cursor
   blinks at the insertion point.
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .iksow0 .ul2kfp,
.icon-card:hover .iksow0 .ul2kfp {
  animation: jfr6ia 0.6s ease both;
  transform-origin: left center;
}
.si-icon-cell:hover .iksow0 .uzu1iw,
.icon-card:hover .iksow0 .uzu1iw {
  animation: t19j22 0.6s steps(2) infinite;
}
.si-icon-cell:hover .iksow0 .x07tnw,
.icon-card:hover .iksow0 .x07tnw {
  animation: xhkd0x 0.3s ease;
}
@keyframes jfr6ia {
  0%   { transform: scaleX(0); opacity: 0; }
  100% { transform: scaleX(1); opacity: 0.7; }
}
@keyframes xhkd0x {
  0%   { opacity: 1; }
  50%  { opacity: 0.3; }
  100% { opacity: 1; }
}

/* ──── 9. REGENERATE ──────────────────────────────────────────
   Animation story: Both arrows spin in opposite directions,
   creating a spinning refresh effect with glow trail.
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .j474hh svg,
.icon-card:hover .j474hh svg {
  animation: azitsa 0.8s cubic-bezier(0.4, 0, 0.2, 1);
  transform-origin: center;
  filter: drop-shadow(0 0 3px rgba(0, 212, 255, 0.4));
}
@keyframes azitsa {
  0%   { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* ──── 10. REASONING ──────────────────────────────────────────
   Animation story: Nodes pop in sequentially (top to bottom),
   links draw in between them, center hub pulses last.
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .nzis6r .t0kc87,
.icon-card:hover .nzis6r .t0kc87 {
  animation: pd56ye 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
.si-icon-cell:hover .nzis6r .r0ovef,
.icon-card:hover .nzis6r .r0ovef {
  animation: pd56ye 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) 0.1s both;
}
.si-icon-cell:hover .nzis6r .l2oxwr,
.icon-card:hover .nzis6r .l2oxwr {
  animation: gcttak 0.3s ease 0.15s both;
}
.si-icon-cell:hover .nzis6r .ac8u1s,
.icon-card:hover .nzis6r .ac8u1s {
  animation: gcttak 0.3s ease 0.2s both;
}
.si-icon-cell:hover .nzis6r .nsogbz,
.icon-card:hover .nzis6r .nsogbz {
  animation: gcttak 0.3s ease 0.25s both;
}
.si-icon-cell:hover .nzis6r .bhnx8a,
.icon-card:hover .nzis6r .bhnx8a {
  animation: qdtcwz 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) 0.3s both;
  transform-origin: center;
}
.si-icon-cell:hover .nzis6r .kunedt,
.icon-card:hover .nzis6r .kunedt {
  animation: gcttak 0.3s ease 0.5s both;
}
.si-icon-cell:hover .nzis6r .wpcc46,
.icon-card:hover .nzis6r .wpcc46 {
  animation: gcttak 0.3s ease 0.55s both;
}
.si-icon-cell:hover .nzis6r .qmfx7j,
.icon-card:hover .nzis6r .qmfx7j {
  animation: pd56ye 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) 0.6s both;
}
.si-icon-cell:hover .nzis6r .zqq3qk,
.icon-card:hover .nzis6r .zqq3qk {
  animation: pd56ye 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) 0.7s both;
}
@keyframes gcttak {
  0%   { opacity: 0; }
  100% { opacity: 0.4; }
}
@keyframes qdtcwz {
  0%   { transform: scale(0); opacity: 0; }
  70%  { transform: scale(1.2); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}

/* ━━━ V2 UNIQUE ANIMATIONS (40 icons) ━━━━━━━━━━━━━━━━━━━━━━━
   Every icon has its own animation story driven by Socratic
   analysis: "What is this icon's core concept? What motion
   tells that story?"
   ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━ */

/* ──── AGENT ──────────────────────────────────────────────────
   Concept: AI robot assistant
   Story: Robot eyes blink (quick close-open), visor flickers
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .qn0atl .uo31n6,
.icon-card:hover .qn0atl .uo31n6 {
  animation: mh93f0 0.4s ease 0.1s both;
}
.si-icon-cell:hover .qn0atl .uyc2tb,
.icon-card:hover .qn0atl .uyc2tb {
  animation: mh93f0 0.4s ease 0.1s both;
}
.si-icon-cell:hover .qn0atl .z8kw4l,
.icon-card:hover .qn0atl .z8kw4l {
  animation: xqefs4 0.6s ease 0.3s both;
}
.si-icon-cell:hover .qn0atl svg,
.icon-card:hover .qn0atl svg {
  filter: drop-shadow(0 0 4px rgba(255, 107, 53, 0.3));
}
@keyframes mh93f0 {
  0%   { transform: scaleY(1); }
  40%  { transform: scaleY(0.1); }
  100% { transform: scaleY(1); }
}
@keyframes xqefs4 {
  0%   { opacity: 0.3; }
  30%  { opacity: 0.8; }
  60%  { opacity: 0.2; }
  100% { opacity: 0.3; }
}

/* ──── AGENT-GROUP ─────────────────────────────────────────────
   Concept: Multiple agents collaborating
   Story: Second robot slides in from right, joins the first
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .wtegtf .dbgfxl,
.icon-card:hover .wtegtf .dbgfxl {
  animation: livtwv 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
.si-icon-cell:hover .wtegtf .jvy325,
.icon-card:hover .wtegtf .jvy325 {
  animation: livtwv 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) 0.1s both;
}
.si-icon-cell:hover .wtegtf svg,
.icon-card:hover .wtegtf svg {
  filter: drop-shadow(0 0 3px rgba(255, 107, 53, 0.25));
}
@keyframes livtwv {
  0%   { transform: translateX(6px); opacity: 0; }
  100% { transform: translateX(0); opacity: 1; }
}

/* ──── AGENT-STOP ─────────────────────────────────────────────
   Concept: Emergency halt
   Story: Inner stop block throbs urgently (scale pulse)
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .cu4kkk .jllhqf,
.icon-card:hover .cu4kkk .jllhqf {
  animation: r4mwd2 0.5s ease infinite;
  transform-origin: center;
}
.si-icon-cell:hover .cu4kkk .m7c0tn,
.icon-card:hover .cu4kkk .m7c0tn {
  animation: cwl4a0 0.3s ease;
  transform-origin: center;
}
.si-icon-cell:hover .cu4kkk svg,
.icon-card:hover .cu4kkk svg {
  filter: drop-shadow(0 0 4px rgba(255, 45, 135, 0.4));
}
@keyframes r4mwd2 {
  0%, 100% { transform: scale(1); opacity: 0.8; }
  50%      { transform: scale(1.15); opacity: 1; }
}
@keyframes cwl4a0 {
  0%, 100% { transform: translateX(0); }
  25%  { transform: translateX(-1.5px); }
  75%  { transform: translateX(1.5px); }
}

/* ──── AGENT-WORKFLOW ─────────────────────────────────────────
   Concept: Sequential process flow
   Story: Nodes light up in sequence (1→2→3→4) showing flow
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .sidg38 .ptkbdc,
.icon-card:hover .sidg38 .ptkbdc {
  animation: ih76k4 0.4s ease both;
}
.si-icon-cell:hover .sidg38 .uyaz7j,
.icon-card:hover .sidg38 .uyaz7j {
  animation: gcttak 0.2s ease 0.15s both;
}
.si-icon-cell:hover .sidg38 .vmht0x,
.icon-card:hover .sidg38 .vmht0x {
  animation: ih76k4 0.4s ease 0.2s both;
}
.si-icon-cell:hover .sidg38 .ar7zf9,
.icon-card:hover .sidg38 .ar7zf9 {
  animation: gcttak 0.2s ease 0.25s both;
}
.si-icon-cell:hover .sidg38 .txfzvm,
.icon-card:hover .sidg38 .txfzvm {
  animation: ih76k4 0.4s ease 0.35s both;
}
.si-icon-cell:hover .sidg38 .hefydh,
.icon-card:hover .sidg38 .hefydh {
  animation: gcttak 0.2s ease 0.4s both;
}
.si-icon-cell:hover .sidg38 .j0vcty,
.icon-card:hover .sidg38 .j0vcty {
  animation: gcttak 0.2s ease 0.45s both;
}
.si-icon-cell:hover .sidg38 .d1u38q,
.icon-card:hover .sidg38 .d1u38q {
  animation: ih76k4 0.4s ease 0.5s both;
}
@keyframes ih76k4 {
  0%   { opacity: 0.3; transform: scale(0.8); }
  50%  { opacity: 1; transform: scale(1.2); }
  100% { opacity: 0.8; transform: scale(1); }
}

/* ──── AI-HELP ──────────────────────────────────────────────
   Concept: Getting assistance
   Story: Question mark wobbles side to side (seeking answer)
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .zrffi6 .u5o9aq,
.icon-card:hover .zrffi6 .u5o9aq {
  animation: ux1rwe 0.5s ease;
  transform-origin: center bottom;
}
.si-icon-cell:hover .zrffi6 .r6ktma,
.icon-card:hover .zrffi6 .r6ktma {
  animation: q0e7v2 0.4s ease 0.3s both;
}
.si-icon-cell:hover .zrffi6 svg,
.icon-card:hover .zrffi6 svg {
  filter: drop-shadow(0 0 3px rgba(0, 212, 255, 0.3));
}
@keyframes ux1rwe {
  0%   { transform: rotate(0); }
  25%  { transform: rotate(-8deg); }
  75%  { transform: rotate(8deg); }
  100% { transform: rotate(0); }
}

/* ──── AI-HISTORY ──────────────────────────────────────────────
   Concept: Going back in time
   Story: Clock hands spin backward (rewinding)
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .uapabx .y7i3vf,
.icon-card:hover .uapabx .y7i3vf {
  animation: zt1kot 0.6s ease;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .uapabx svg,
.icon-card:hover .uapabx svg {
  filter: drop-shadow(0 0 3px rgba(0, 212, 255, 0.25));
}
@keyframes zt1kot {
  from { transform: rotate(0); }
  to   { transform: rotate(-180deg); }
}

/* ──── AI-HOME ────────────────────────────────────────────────
   Concept: Home/dashboard base
   Story: Roof lifts up slightly (welcoming), door knob appears
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .x2xlvb .nu0cva,
.icon-card:hover .x2xlvb .nu0cva {
  animation: hdref5 0.5s ease;
}
.si-icon-cell:hover .x2xlvb .wcjgpz,
.icon-card:hover .x2xlvb .wcjgpz {
  animation: q0e7v2 0.4s ease 0.25s both;
}
.si-icon-cell:hover .x2xlvb svg,
.icon-card:hover .x2xlvb svg {
  filter: drop-shadow(0 0 3px rgba(0, 212, 255, 0.25));
}
@keyframes hdref5 {
  0%   { transform: translateY(0); }
  40%  { transform: translateY(-2px); }
  100% { transform: translateY(0); }
}

/* ──── AI-MENU ────────────────────────────────────────────────
   Concept: Navigation menu
   Story: Bars slide in with staggered delay
   ──────────────────────────────────────────────────────────── */
.si-icon-cell:hover .ldi6tn .rbc1js,
.icon-card:hover .ldi6tn .rbc1js {
